MAP_HISTORY = ("iba/app/BUILD.md; GOVERNANCE.md's dated sections to 2026-10-21 at "
               "archive/docs/governance-md-history-to-20261021.md")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--db", default=DEFAULT_DB)
    ap.add_argument("--dry-run", action="store_true")
    a = ap.parse_args()
    conn = sqlite3.connect(a.db)
    if a.dry_run:
        print(f"DRY RUN -- 1 new rule, {len(RULES)} rule texts, {len(SETTINGS)} settings, 1 map row")
        return 0
    n = 0
    one = lambda sql, p=(): conn.execute(sql, p).fetchone()  # noqa: E731
    with conn:
        cls, key, text, src = NEW_RULE
        if not one("SELECT 1 FROM cfg_behaviour_rule WHERE class=? AND rule_key=?", (cls, key)):
            apply_logged(conn, RUN_ID, "cfg_behaviour_rule", "insert", {}, {
                "class": cls, "rule_key": key, "rule_text": text, "source": src,
                "enforced_by": "Context-delivered at session start (rule 81); session-close checks "
                               "control files for struck-through or superseded text (#2186).",
                "added_at": NOW, "active": 1, "enforcement_status": "context_delivered"}); n += 1
        for rid, new in RULES.items():
            row = one("SELECT rule_text, source FROM cfg_behaviour_rule WHERE id=?", (rid,))
            if row is None or row[0] == new:
                continue
            apply_logged(conn, RUN_ID, "cfg_behaviour_rule", "update", {"id": rid},
                         {"rule_text": new, "source": (row[1] or "") + MOVED + RUN_ID + "."}); n += 1
        for k, new in SETTINGS.items():
            row = one("SELECT value FROM cfg_setting WHERE key=?", (k,))
            target = json.dumps(new)
            if row is None or row[0] == target:
                continue
            apply_logged(conn, RUN_ID, "cfg_setting", "update", {"key": k}, {"value": target}); n += 1
        row = one("SELECT history_home FROM cfg_control_home WHERE kind='mechanism'")
        if row and row[0] != MAP_HISTORY:
            apply_logged(conn, RUN_ID, "cfg_control_home", "update", {"kind": "mechanism"},
                         {"history_home": MAP_HISTORY}); n += 1
    print(f"{n} audited cfg_* write(s) (run {RUN_ID})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
